void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 resolution = iResolution.xy;
    vec2 coordonneesFragment = fragCoord;
    float temps = iTime;

    float distanceParcourue = 0.0;
    float echelleAccumulee = 0.0;
    float distanceMinimaleOrbite = 0.0;
    float facteurEchelle = 0.0;
    float distanceSurface = 0.0;
    float lumiereAccumulee = 0.0;

    vec3 directionRegard = normalize(vec3(0.18 * cos(temps * 0.6), -0.08 * sin(temps * 0.4), 1.0));
    vec3 vecteurDroit = vec3(-directionRegard.z, 0.0, directionRegard.x);
    vec3 directionRayon = mat3(vecteurDroit, cross(vecteurDroit, directionRegard), directionRegard) * normalize(vec3((coordonneesFragment - resolution * 0.5) / resolution.y, 1.0));
    vec3 positionCourante;

    vec2 coordonneesPerturbees, coordonneesRepetees;

    for (int indexEtape = 0; indexEtape < 110; indexEtape++) {
        positionCourante = vec3(1.2 * sin(temps * 0.6), 0.8 * cos(temps * 0.4), 4.0 * temps) + directionRayon * distanceParcourue;
        coordonneesPerturbees = positionCourante.xy - vec2(1.2 * sin(positionCourante.z * 0.15), 0.8 * cos(positionCourante.z * 0.1));
        coordonneesRepetees = mod(coordonneesPerturbees + 2.0, 4.0) - 2.0;

        echelleAccumulee = 1.0;
        distanceMinimaleOrbite = 9.0;

        for (int indexFractal = 0; indexFractal < 4; indexFractal++) {
            coordonneesRepetees = clamp(coordonneesRepetees, -1.0, 1.0) * 2.0 - coordonneesRepetees;
            coordonneesRepetees *= facteurEchelle = max(1.25 / max(dot(coordonneesRepetees, coordonneesRepetees), 0.08), 0.55);
            echelleAccumulee *= facteurEchelle;
            distanceMinimaleOrbite = min(distanceMinimaleOrbite, length(coordonneesRepetees));
        }

        distanceSurface = abs(max((abs(coordonneesRepetees.x) - 0.15) / echelleAccumulee, 1.4 - length(coordonneesPerturbees)));
        lumiereAccumulee += 0.002 / (0.05 + 15.0 * distanceSurface) + 0.0006 / (0.02 + 1.5 * distanceMinimaleOrbite);
        distanceParcourue += max(distanceSurface * 0.35, 0.004);
    }

    fragColor = vec4(pow(lumiereAccumulee, 1.4));
}
